{{-- Visit recordings (App\Support\Clarity), only on the pages it allows. Not for crawlers, nor when the
     browser asks sites not to track it or the visitor turned recordings off on the cookie policy page.
     Nothing happens until the page has loaded and the browser is idle, so the page itself is never slower.
     Then the server is asked once per browser tab whether this visitor may be recorded (their country is
     known only to it), and the recorder loads, in the background, as its install code does. --}}
<script>(function(){try{var n=navigator,d=document;if(/bot|crawl|spider|slurp|lighthouse|headless/i.test(n.userAgent||''))return;if(n.globalPrivacyControl===true||n.doNotTrack==='1')return;var off=null,known=null;try{off=localStorage.getItem(@json(\App\Support\Clarity::OFF_KEY));known=sessionStorage.getItem('listen_recording');}catch(e){}if(off==='1'||known==='0')return;var go=function(){(function(c,l,a,r,i,t,y){c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};t=l.createElement(r);t.async=1;t.src='https://www.clarity.ms/tag/'+i;y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);})(window,d,'clarity','script',@json($projectId));},run=function(){if(known==='1'){go();return;}if(!window.fetch)return;fetch(@json(route('visit-check', [], false)),{credentials:'omit',cache:'no-store'}).then(function(r){return r.ok?r.json():{};}).then(function(j){var ok=!!(j&&j.record===true);try{sessionStorage.setItem('listen_recording',ok?'1':'0');}catch(e){}if(ok)go();}).catch(function(){});},idle=function(){(window.requestIdleCallback||function(f){setTimeout(f,200);})(run,{timeout:5000});};if(d.readyState==='complete')idle();else addEventListener('load',idle,{once:true});}catch(e){}})();</script>
